 "content": "def transform(grid):
    # Keep the lower panel and place the selected upper pattern immediately above its 1-shape.
    h, w = len(grid), len(grid[0])
    sep = next(r for r, row in enumerate(grid) if all(x == 5 for x in row))
    lower = [(r, c) for r in range(sep + 1, h) for c in range(w) if grid[r][c] == 1]
    lo_r = min(r for r, c in lower)
    lo_c = min(c for r, c in lower)
    objects = {}
    for r in range(sep):
        for c in range(w):
            if grid[r][c]:
                objects.setdefault(grid[r][c], []).append((r, c))
    # The colored object that differs from the lower shape and appears at the rightmost position.
    color = max(objects, key=lambda v: max(c for r, c in objects[v]))
    obj = objects[color]
    r0, c0 = min(r for r, c in obj), min(c for r, c in obj)
    out = [[0] * w for _ in range(h - sep - 1)]
    for r, c in lower:
        out[r - sep - 1][c] = 1
    for r, c in obj:
        rr = lo_r - sep - 2 + r - r0
        cc = lo_c + c - c0
        if 0 <= rr < len(out) and 0 <= cc < w:
            out[rr][cc] = color
    return out
